import unittest
from shop.dto.customer import CustomerDTO


class HiddenCustomerTests(unittest.TestCase):
    def test_from_dict_strips_name_and_ignores_unknown_keys(self):
        c = CustomerDTO.from_dict({"id": "c1", "name": "  Ada  ", "email": "a@x.io", "extra": 1})
        self.assertEqual(c.name, "Ada")
        self.assertEqual(c.id, "c1")

    def test_to_dict_shape(self):
        c = CustomerDTO(id="c1", name="Ada", email="a@x.io")
        self.assertEqual(c.to_dict(), {"id": "c1", "name": "Ada", "email": "a@x.io"})

    def test_round_trip(self):
        d = {"id": "c2", "name": "Bo", "email": "b@x.io"}
        self.assertEqual(CustomerDTO.from_dict(d).to_dict(), d)


if __name__ == "__main__":
    unittest.main()

