    def test_boundary_one(self):
        self.assertEqual(shipping_cost(1), 4)

    def test_medium(self):
        self.assertEqual(shipping_cost(3), 9)

    def test_boundary_five(self):
        self.assertEqual(shipping_cost(5), 9)

    def test_heavy(self):
        self.assertEqual(shipping_cost(20), 25)

    def test_out_of_range(self):
        with self.assertRaises(ValueError):
            shipping_cost(0)
        with self.assertRaises(ValueError):
            shipping_cost(21)


