"""In-memory order repository."""


class OrdersRepo:
    def __init__(self):
        self._items = {}

    def add(self, order):
        if order["id"] in self._items:
            raise KeyError("duplicate id: %s" % order["id"])
        self._items[order["id"]] = order

    def get(self, order_id):
        return self._items[order_id]

    def list(self):
        return sorted(self._items.values(), key=lambda o: o["id"])

    def delete(self, order_id):
        del self._items[order_id]

